def preparar_dados(apps, schema_editor):
    """Cria o curso, liga as matérias a ele e troca os códigos ENG0382/ENG0383."""
    Curso = apps.get_model('matricula', 'Curso')
    Disciplina = apps.get_model('matricula', 'Disciplina')

    curso, _ = Curso.objects.get_or_create(nome='Engenharia de Computação')
    Disciplina.objects.filter(curso__isnull=True).update(curso=curso)

    for antigo, novo in (('ENG0382', 'INF0382'), ('ENG0383', 'INF0383')):
        if Disciplina.objects.filter(codigo=antigo).exists() and \
                not Disciplina.objects.filter(codigo=novo).exists():
            Disciplina.objects.filter(codigo=antigo).update(codigo=novo)


